B.a6u=new A.dz("\u0110\u0103ng nh\u1eadp \u0111\u1ec3 s\u1eed d\u1ee5ng SMGS. T\xe0i kho\u1ea3n tr\u1ea3i nghi\u1ec7m ch\u1ec9 t\u1ed3n t\u1ea1i trong phi\xean n\xe0y.",B.bb,null)
B.a6v=new A.dz("Thanh ph\xe1t ch\u1ec9 m\xf4 ph\u1ecfng thao t\xe1c, ch\u01b0a c\xf3 \xe2m thanh. B\u1ea1n c\xf3 th\u1ec3 \u0111\u1ecdc to\xe0n b\u1ed9 n\u1ed9i dung \u1edf tr\xean.",B.bb,null)
B.a6w=new A.dz("G\xf3p \xfd hi\u1ec7n ch\u1ec9 \u0111\u01b0\u1ee3c ghi nh\u1eadn trong b\u1ea3n tr\u1ea3i nghi\u1ec7m.",B.bb,null)
B.a6x=new A.dz("H\u1ecfi \u0111\xe1p m\u1eabu t\u1eeb n\u1ed9i dung b\u1ed9 s\u01b0u t\u1eadp. Tr\u1ee3 l\xfd th\xf4ng minh s\u1ebd \u0111\u01b0\u1ee3c k\u1ebft n\u1ed1i sau.",B.bb,null)
B.a6y=new A.dz("C\xe0i \u0111\u1eb7t v\xe0 d\u1eef li\u1ec7u ch\u1ec9 \u0111\u01b0\u1ee3c gi\u1eef trong phi\xean tr\u1ea3i nghi\u1ec7m hi\u1ec7n t\u1ea1i.",B.bb,null)
B.a6B=new A.dz("L\u1ed9 tr\xecnh \u0111\u01b0\u1ee3c g\u1ee3i \xfd t\u1eeb b\u1ed9 s\u01b0u t\u1eadp m\u1eabu. B\u1ea1n c\xf3 th\u1ec3 \u0111i\u1ec1u ch\u1ec9nh nh\u1ecbp tham quan t\xf9y \xfd.",B.bb,null)
B.a6D=new A.dz("B\u1ea1n c\xf3 th\u1ec3 tra c\u1ee9u b\u1ed9 s\u01b0u t\u1eadp m\xe0 kh\xf4ng c\u1ea7n c\u1ea5p quy\u1ec1n m\xe1y \u1ea3nh.",B.bb,null)
B.a6E=new A.dz("Tr\u1ea3i nghi\u1ec7m m\xf4 ph\u1ecfng tr\xean web, kh\xf4ng s\u1eed d\u1ee5ng m\xe1y \u1ea3nh.",B.bb,null)
B.a6F=new A.dz("S\u01a1 \u0111\u1ed3 minh h\u1ecda, kh\xf4ng \u0111\u1ecbnh v\u1ecb tr\u1ef1c ti\u1ebfp. T\xecm ph\xf2ng theo bi\u1ec3n ch\u1ec9 d\u1eabn t\u1ea1i b\u1ea3o t\xe0ng.",B.bb,null)
B.a6G=new A.dz("D\u1ecbch v\u1ee5 \u0111\u01b0\u1ee3c \u0111\u0103ng k\xfd cho m\u1ed9t ng\xe0y kh\xe1c. Xem l\u1ea1i ng\xe0y s\u1eed d\u1ee5ng trong s\u1ed5 tay.",B.bb,null)
B.a6H=new A.dz("\u0110\u01b0a m\xe3 n\xe0y cho nh\xe2n vi\xean t\u1ea1i c\u1ed5ng. \u0110\xe2y l\xe0 v\xe9 m\xf4 ph\u1ecfng, ch\u01b0a c\xf3 gi\xe1 tr\u1ecb v\xe0o c\u1eeda th\u1ef1c t\u1ebf.",B.bb,null)
B.a6I=new A.dz("B\u1ea1n \u0111ang d\xf9ng b\u1ea3n tr\u1ea3i nghi\u1ec7m. L\u1ecbch s\u1eed, m\u1ee5c \u0111\xe3 l\u01b0u v\xe0 k\u1ebft qu\u1ea3 \u0111\u01b0\u1ee3c gi\u1eef trong phi\xean hi\u1ec7n t\u1ea1i; t\u1ea3i l\u1ea1i trang s\u1ebd \u0111\u1eb7t l\u1ea1i d\u1eef li\u1ec7u.",B.bb,null)
B.a6J=new A.dz("B\u1ea1n c\xf3 th\u1ec3 mua ri\xeang v\xe9 v\xe0o c\u1eeda, ri\xeang H\u01b0\u1edbng d\u1eabn s\u1ed1 ho\u1eb7c ch\u1ecdn g\xf3i k\u1ebft h\u1ee3p. Gi\xe1 v\xe0 thanh to\xe1n hi\u1ec7n ch\u1ec9 l\xe0 m\xf4 ph\u1ecfng.",B.bb,null)
B.a6K=new A.dz("\u0110\xe2y l\xe0 k\u1ebft qu\u1ea3 m\xf4 ph\u1ecfng. Kh\xf4ng c\xf3 ti\u1ec1n \u0111\u01b0\u1ee3c thu.",B.bb,null)
